                    {
                        if (!empty($rnd_keywords) && in_array($word, $rnd_keywords)) continue;

                        $rnd_keywords[] = $word;
                        $count++;
                    }
                    if ($count == $bb_cfg['keyword_word_count']) break;
                }
                $rnd_keywords = implode(', ', $rnd_keywords);
                if ($bb_cfg['append_keywords_first']) $rnd_keywords = ', ' . $rnd_keywords;
